-- 2264 🏋️ Exercises from the book "pep-guardiola-88-attacking-combinations-and-positional-patterns-of-play-direct-f" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'pep-guardiola-88-attacking-combinations-and-positional-patterns-of-play-direct-f');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Build-up from goal kick: 3v3 out wide', 'phase_of_play', 'opposed', 'in_possession', 22, 24, 'Building Up Play from the GK Practice Example: 3v3 Situation Out Wide (Examples A-C)', 'Guardiola (Bayern Munich, Doha 17 Jan 2015)', 'Reading which option the opponent blocks when building out from the GK and using the free man (FB, DM or winger) out wide.', 'Own half of a full pitch from a goal kick; GK with balls, centre back, full back, defensive midfielder and winger on one side against an opposing winger, midfielder and full back (3v3 out wide), rest of both teams in shape.', 'GK plays to the CB, who carries forward. In Example A the pass to the FB is blocked and the DM is marked, so the winger drops (dragging his marker), takes the CB''s pass and sets first time to the FB, who runs on and dribbles into the space.', NULL, 'Example B: pass to DM is blocked and FB is marked, so the dropping winger sets first time inside to the DM, who drives forward. Example C: DM is marked and the opposing winger shifts to block the dropping winger, so the CB plays straight out to the free FB, who carries forward.', 'Winger''s drop pulls his marker and opens space behind; first-time set passes; the receiver attacks the space created with the ball.', 'GK + 4 attackers v 3 defenders on the ball side (full teams in shape)', 8, 22, 'own half of a full pitch', 52.5, 68.0, NULL, false, true, true, NULL, 10),
  ('Both attacking mids combine through the centre', 'combination', 'unopposed', 'in_possession', 31, 31, '1. Both Attacking Midfielders Combine to Attack Through the Centre', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Combining the two attacking midfielders in the half spaces to break through the centre and finish.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', 'CB (5) to inverted RB (3), inside to DM (25), who carries and plays diagonally to left AM (17) in the half space. AM 17 shifts across and passes to the other AM (21) on the move, who dribbles into the box and shoots; forward and both wingers attack the box for rebounds.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 20),
  ('AM takes forward''s lay-off, ball in behind to winger', 'combination', 'unopposed', 'in_possession', 32, 32, '2. Attacking Midfielder Moves Inside to Receive Forward''s Lay-off and Pass in Behind to the Winger', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Using a set from the forward so the far attacking midfielder can release the winger in behind.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to inverted RB 3, inside to DM 25, who carries and plays diagonally to AM 17 in the half space. 17 finds the forward (10), who sets back to AM 21 shifting into the centre; 21 opens up and plays a diagonal ball in behind for the right winger (7) to finish.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 30),
  ('Half-space receive, dribble inside, winger in behind', 'combination', 'unopposed', 'in_possession', 33, 33, '3. Attacking Midfielder Receives in the "Half Space," Dribbles Inside and Plays in Behind to the Winger', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Receiving in the half space, carrying inside and releasing the far-side winger for a cut-back.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to 3, inside to DM 25, diagonal to AM 17 in the half space. 17 dribbles inside and forward, then slides the left winger (19) in behind; 19 cuts back for runners (21, 10, 7) and AM 21 finishes centrally in the example.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 40),
  ('AM takes forward''s lay-off, dribbles in and scores', 'combination', 'unopposed', 'in_possession', 34, 34, '4. Attacking Midfielder Moves Inside to Receive Forward''s Lay-off, Dribble in Behind and Finish', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Short set from a dropping forward for an attacking midfielder to drive through the line and finish.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to 3, inside to DM 25, who plays into the forward (10) dropping slightly. AM 21 shifts across to take 10''s lay-off, dribbles into the box past the mannequin line and shoots.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 50),
  ('Half-space pass in behind after forward''s set', 'combination', 'unopposed', 'in_possession', 35, 35, '5. Attacking Midfielder''s Pass in Behind to Winger from the "Half Space" After the Forward''s Lay-off', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Forward links play so the half-space midfielder can release the winger, ending in a cut-back finish.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to 3, inside to DM 25, into the dropping forward (10), who sets to AM 17 in the half space. 17 plays in behind for winger 19, who carries on and cuts back for runners (21, 10, 7); the forward scores centrally in the example.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 60),
  ('Forward set, through ball between mannequins', 'combination', 'unopposed', 'in_possession', 36, 36, '6. Defensive Midfielder''s Pass to the Forward + Lay-off to the Attacking Midfielder for Pass in Behind', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Third-man combination through the centre: forward sets, one AM threads the other through.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to 3, inside to DM 25, into the forward (10), who sets to AM 21 moving inside. 21 slips a through pass between the two central mannequins for AM 17''s diagonal run; 17 takes a touch and shoots.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 70),
  ('Full back into forward, set, through ball', 'combination', 'unopposed', 'in_possession', 37, 37, '7. Full Back''s Pass to Forward + Lay-off to the Attacking Midfielder for a Pass in Behind', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Inverted full back breaking a line with a diagonal into the forward to start a third-man combination.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to inverted RB 3, who steps forward and plays diagonally into the dropping forward (10). 10 sets to AM 21 moving inside, who threads a pass between the central mannequins for AM 17''s diagonal run; 17 finishes in the box.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 80),
  ('DM''s diagonal aerial ball to winger, cut-back', 'combination', 'unopposed', 'in_possession', 38, 38, '8. Defensive Midfielder''s Diagonal Aerial Pass in Behind to the Winger + Cut Back', 'Guardiola (Man City, Etihad Campus 12 Jul 2017)', 'Circulating across the back to free the DM for a long diagonal over the line to the far winger.', 'Attacking half of a full pitch with a GK in goal and 6 red mannequins in a line just outside the penalty area as the back line. Players in a 4-3-3 (2-3-2-3 shape with inverted full backs in the half spaces, wingers wide); 2 players per position in two teams of 10 outfield players, coaches with balls on each touchline feed the centre backs.', '5 to left CB 30, to inverted LB 11, inside to DM 25 arriving on a curved run. 25 opens up and lofts a diagonal ball in behind to right winger 7, who carries on and cuts back while 17, 10 and 19 attack the box; 19 scores at the back post in the example.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Wingers hold width to pin defenders and keep the half spaces free; attacking midfielders receive in the half space and turn; timed runs into the box after the final ball.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 90),
  ('Patterns v 1 defender + midfield mannequins', 'combination', 'passive', 'in_possession', 39, 39, 'Attacking Positional Pattern of Play Practice Variation: Add 1 Defender and 2 Midfield Mannequins', 'Guardiola (Man City, Etihad Campus 8 May 2018)', 'Running the same build-up patterns with a live defender to beat at the finish and obstacles in the passing lanes.', 'As the inverted full back set-up (GK, line of mannequins outside the box, 2 players per position, coaches with balls by each centre back) plus 1 live defender in the box and 2 extra mannequins in midfield in front of the DM.', 'Teams repeat the 4-3-3 patterns from the previous pages, but the final action is contested by one defender, either 1v1 after a ball in behind or defending a low cross into the centre.', 'Two teams take turns running the pattern the coach calls; after finishing, the group jogs back to its starting spots and the other team goes.', NULL, 'Find passing lanes around the midfield mannequins; finish under pressure, attack crosses ahead of the defender.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 100),
  ('Forward''s set, AM plays winger in behind', 'combination', 'unopposed', 'in_possession', 43, 43, '1. Forward''s Lay-off from Defensive Midfielder''s Pass for Attacking Midfielder to Play in Behind to Winger', 'Guardiola (Man City, pre-season Houston 20 Jul 2017)', 'Linking DM, forward and attacking midfielder to release the winger for a low cross.', 'Attacking half of a full pitch with a GK and 5 mannequins set narrower across the edge of the box. Players in a 4-3-3 with regular full backs staying wide and deep; 2 players per position in two teams of 10 outfield players, coaches with balls near each centre back.', '5 to 30, to AM 21 in the half space; DM 25 curves across to take 21''s set, drives on and plays into the forward (10). 10 sets back to AM 17 coming inside, who opens up and plays diagonally in behind to winger 7; 7 crosses low for 21, 19 and 10 arriving (10 scores in the example).', 'The two teams run the called pattern alternately, jogging back to start after each finish.', NULL, 'Defensive midfielder curves his run to offer for the lay-off; attacking midfielder receives in the half space; forward drops to link; timing of third-man runs.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 110),
  ('Forward''s dummy for AM third-man run', 'combination', 'unopposed', 'in_possession', 44, 44, '2. Forward''s "Dummy" of Defensive Midfielder''s Pass for the Attacking Midfielder to Run onto and Score', 'Guardiola (Man City, pre-season Houston 20 Jul 2017)', 'Using a forward''s step-over to let the ball run through to a third-man runner.', 'Attacking half of a full pitch with a GK and 5 mannequins set narrower across the edge of the box. Players in a 4-3-3 with regular full backs staying wide and deep; 2 players per position in two teams of 10 outfield players, coaches with balls near each centre back.', '30 across to 5, into AM 17 in the half space; DM 25 curves across to take the set and passes towards the forward (10), who steps over it. AM 21 from the left times a third-man run onto the ball, carries on and shoots.', 'The two teams run the called pattern alternately, jogging back to start after each finish.', NULL, 'Defensive midfielder curves his run to offer for the lay-off; attacking midfielder receives in the half space; forward drops to link; timing of third-man runs.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 120),
  ('Forward''s first-time ball for third-man run', 'combination', 'unopposed', 'in_possession', 45, 45, '3. Forward Plays Through Ball from Defensive Midfielder''s Pass for the Attacking Midfielder''s Third Man Run', 'Guardiola (Man City, pre-season Houston 20 Jul 2017)', 'Dropping forward playing first time in behind for the far attacking midfielder''s third-man run.', 'Attacking half of a full pitch with a GK and 5 mannequins set narrower across the edge of the box. Players in a 4-3-3 with regular full backs staying wide and deep; 2 players per position in two teams of 10 outfield players, coaches with balls near each centre back.', '5 across to 30, into AM 21 in the half space; DM 25 curves across for the set, carries forward and passes to the forward (10). 10 drops and plays first time in behind for AM 17''s run, who dribbles into the box and finishes.', 'The two teams run the called pattern alternately, jogging back to start after each finish.', NULL, 'Defensive midfielder curves his run to offer for the lay-off; attacking midfielder receives in the half space; forward drops to link; timing of third-man runs.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 130),
  ('Central combination, aerial switch, low cross', 'combination', 'unopposed', 'in_possession', 46, 46, '4. Defensive Midfielder''s Combination Play in the Centre + Diagonal Aerial Pass in Behind to the Winger', 'Guardiola (Man City, pre-season Houston 20 Jul 2017)', 'Short combinations in the centre to free the DM for a lofted diagonal to the far winger and a low cross.', 'Attacking half of a full pitch with a GK and 5 mannequins set narrower across the edge of the box. Players in a 4-3-3 with regular full backs staying wide and deep; 2 players per position in two teams of 10 outfield players, coaches with balls near each centre back.', '30 across to 5, into AM 17 in the half space; DM 25 curves across for the set and passes to AM 21, who moves central and sets back to 25 stepping forward. 25 lofts a diagonal in behind to left winger 19, who dribbles on and crosses low; forward 10 scores centrally.', 'The two teams run the called pattern alternately, jogging back to start after each finish.', NULL, 'Defensive midfielder curves his run to offer for the lay-off; attacking midfielder receives in the half space; forward drops to link; timing of third-man runs.', '2 teams of 10 outfield players + GK, 2 per position, alternate', 11, 21, 'attacking half of a full pitch', 52.5, 68.0, NULL, true, true, true, NULL, 140),
  ('Short-pass switch to winger in behind', 'combination', 'unopposed', 'in_possession', 51, 51, 'Attacking Positional Patterns of Play (4-3-3): Pattern 1', 'Guardiola (Barcelona B)', 'Work the ball across the back and through the half space to free the far winger in behind.', 'Full 4-3-3 team (GK plus 10 outfielders) in their match positions in the attacking half, shadow play with no opponents, finishing on a goal with a keeper.', 'Right back to CB, CB across to left back (skipping the other CB), into the left AM in the half space, back inside to the DM, up to the dropping No.9, who sets the right AM in the half space; he slides the right winger in behind to cross for runners.', NULL, NULL, 'The most creative players must get on the ball in the half space; final pass in behind for the winger.', '11 (10 outfield + GK)', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 150),
  ('Long switch for winger to dribble and cross', 'combination', 'unopposed', 'in_possession', 52, 52, 'Attacking Positional Patterns of Play (4-3-3): Pattern 2', 'Guardiola (Barcelona B)', 'After overloading one side, switch quickly with a long pass to exploit the space on the weak side.', 'Full 4-3-3 team (GK plus 10 outfielders) in their match positions in the attacking half, shadow play with no opponents, finishing on a goal with a keeper.', 'Right back into the DM, back to the left CB, medium pass wide to the left winger, inside to the No.9 moving across, back to the left AM in the half space, who hits a long switch to the right winger; winger dribbles on and crosses for team-mates.', NULL, NULL, NULL, '11 (10 outfield + GK)', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 160),
  ('Aerial ball in behind for AM third-man run', 'combination', 'unopposed', 'in_possession', 53, 53, 'Attacking Positional Patterns of Play (4-3-3): Pattern 3', 'Guardiola (Barcelona B)', 'Attack through the centre with a lofted pass into the path of a third-man runner.', 'Full 4-3-3 team (GK plus 10 outfielders) in their match positions in the attacking half, shadow play with no opponents, finishing on a goal with a keeper.', 'DM back to right CB, across to left back (skipping the other CB), forward to the left winger, inside to the No.9 moving across, back to the left AM in the half space, who chips a diagonal ball in behind for the right AM''s third-man run; he cuts it back for the left winger to score.', NULL, NULL, NULL, '11 (10 outfield + GK)', 11, 11, NULL, NULL, NULL, NULL, true, true, true, NULL, 170),
  ('Poles and hurdles overlap, cross and finish', 'combination', 'unopposed', 'in_possession', 54, 54, 'Attacking Positional Patterns of Play (4-3-3): Pattern 4', 'Guardiola (Barcelona B)', 'High ball speed, timing of runs, concentration and finishing.', 'Attacking half with a goal and keeper; poles, hurdles and ground poles placed along the players'' starting runs; 4-3-3 shape with no opponents.', 'DM dribbles through poles and plays wide to the right winger, who has hopped a hurdle and checked back; winger plays a diagonal ball to the No.9 (who has gone over a hurdle and round a pole) and runs up the line; No.9 sets the right AM and curls into the box; AM receives the lay-off and plays the overlapping winger in wide, then goes inside; winger crosses, left winger skips ground poles and attacks the back post.', 'All players rotate positions; give enough recovery between runs so every pattern is done at full speed.', 'Run the same pattern on the opposite side.', NULL, '5 + GK (DM, both wingers, AM, No.9)', 6, 6, NULL, NULL, NULL, NULL, true, true, true, NULL, 180),
  ('Poles and hurdles, switch to far winger', 'combination', 'unopposed', 'in_possession', 55, 55, 'Attacking Positional Patterns of Play (4-3-3): Pattern 5', 'Guardiola (Barcelona B)', 'High ball speed, timing of runs, concentration and finishing.', 'Attacking half with a goal and keeper; poles, hurdles and ground poles placed along the players'' starting runs; 4-3-3 shape with no opponents.', 'Same start as the overlap pattern (DM through poles, right winger checks back over a hurdle, No.9 over a hurdle and round a pole sets the AM); this time the AM switches play with a diagonal aerial ball to the left winger, who skips the ground poles and crosses while the No.9 attacks the front post and the right winger arrives between them.', 'All players rotate positions; give enough recovery between runs so every pattern is done at full speed.', 'Run the same pattern on the opposite side.', NULL, '5 + GK', 6, 6, NULL, NULL, NULL, NULL, true, true, true, NULL, 190),
  ('Four-player left-side combination and cross', 'combination', 'unopposed', 'in_possession', 56, 56, 'Attacking Positional Patterns of Play (4-3-3): Pattern 6', 'Guardiola (Barcelona B)', 'Focused pattern with the full back high in the opponent''s half: through pass, cross and finish.', 'Attacking third with a goal and keeper; only the four players in the pattern take part, starting from their 4-3-3 positions, no opponents.', 'Left winger with his back to goal sets the left back, who plays a diagonal ball into the No.9; No.9 lays it to the left AM and spins towards the box; AM plays a longer pass high down the flank for the winger to run onto and cross for the No.9''s timed run.', NULL, NULL, NULL, '4 + GK', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 200),
  ('Four-player right-side combination and cross', 'combination', 'unopposed', 'in_possession', 57, 57, 'Attacking Positional Patterns of Play (4-3-3): Pattern 7', 'Guardiola (Barcelona B)', 'Mirror pattern on the right: one-two, through pass, cross and finish.', 'Attacking third with a goal and keeper; only the four players in the pattern take part, starting from their 4-3-3 positions, no opponents.', 'Right back and right winger play a one-two, winger turns and runs; right back finds the No.9, who sets the right AM and attacks the box; AM plays a longer pass into space high on the flank for the winger, who crosses for the No.9.', NULL, NULL, NULL, '4 + GK', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 210),
  ('Both forwards drop, AM third man in behind', 'combination', 'passive', 'in_possession', 64, 64, '3-5-2 Forward''s Lay-off with Third Man Runs Through the Centre: Pattern 1', 'Guardiola (Man City)', 'Use a DM pass and forward lay-off to free an attacking midfielder''s third-man run through the centre.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Ball moves across the back three to the right CB, into the right AM dropping into the half space; DM moves across for the lay-off and finds the dropping centre forward, who sets the deeper second forward; right AM runs beyond and receives the ball in behind, then squares for the centre forward''s curved run to score.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 220),
  ('Lay-off to 2nd forward, AM receives in centre', 'combination', 'passive', 'in_possession', 65, 65, '3-5-2 Forward''s Lay-off with Third Man Runs Through the Centre: Pattern 2', 'Guardiola (Man City)', 'Third-man run from the far attacking midfielder to receive centrally and shoot.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Ball goes across the back three to the left CB, into the left AM in the half space; DM moves across and forward for the lay-off, plays into the centre forward while the second forward drops; centre forward sets the second forward, who feeds the right AM''s third-man run; he dribbles between the mannequins and shoots.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 230),
  ('Lay-off to 2nd forward, AM run in behind', 'combination', 'passive', 'in_possession', 66, 66, '3-5-2 Forward''s Lay-off with Third Man Runs Through the Centre: Pattern 3', 'Guardiola (Man City)', 'DM and forwards combine to send the left attacking midfielder in behind.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Right CB to middle CB, into the left AM dropping into the half space; DM drops then moves across to take the AM''s inside pass, carries forward and plays the centre forward, who sets the second forward; the left AM makes a third-man run to receive in behind and squares for the centre forward to score.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 240),
  ('Fast AM and two-forward combination', 'combination', 'passive', 'in_possession', 67, 67, '3-5-2 Forward''s Lay-off with Third Man Runs Through the Centre: Pattern 4', 'Guardiola (Man City)', 'Quick combinations between an attacking midfielder and both forwards to break through the middle.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Across the back three to the left wing back out wide, inside to the left AM in the half space; DM receives the lay-off and finds the centre forward as the second forward drops; centre forward sets the AM again, who slides the second forward through the middle; he dribbles between the mannequins and shoots.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 250),
  ('DM one-two to build up to forwards', 'combination', 'passive', 'in_possession', 68, 68, '3-5-2 Forward''s Lay-off with Third Man Runs Through the Centre: Pattern 5', 'Guardiola (Man City)', 'DM''s quick combinations with the centre backs to build towards the forwards.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Right CB to middle CB, who dribbles across and plays a one-two with the DM, then on to the left CB and into the left AM in the half space; DM curls forward for the lay-off and plays the centre forward, who passes across for the second forward to run onto, dribble and shoot.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 260),
  ('Switch for overlapping wing back cross', 'combination', 'passive', 'in_possession', 70, 70, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 1', 'Guardiola (Man City)', 'Switch the point of attack through the centre to free the far wing back on an overlap.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Across the back three to the left wing back wide, inside to the left AM in the half space; DM takes the lay-off and plays the dropping second forward, who sets the right AM in the half space; he plays the overlapping right wing back in behind to cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 270),
  ('DM aerial switch to wing back, AM third man', 'combination', 'passive', 'in_possession', 71, 71, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 2', 'Guardiola (Man City)', 'Switch with a DM aerial pass to the far wing back while the attacking midfielder runs as a third man.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Ball across the back to the left wing back, back to the left AM moving across, on to the second forward, who sets the DM''s curved run; DM lofts the ball to the right wing back running forward while the right AM runs between the mannequins; wing back cuts inside to the AM, who squares for the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Short combinations then wing back in behind', 'combination', 'passive', 'in_possession', 72, 72, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 3', 'Guardiola (Man City)', 'Use short one-twos on one side to switch play and release the far wing back.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Middle CB dribbles out, plays the advancing left CB, who finds the dropping left wing back; DM moves across into the half space, plays the dropping centre forward, who returns it to the left AM (one-two); AM finds the advanced right AM, DM moves up for the lay-off and plays the right wing back in behind for a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Forward lay-off switches to wing back', 'combination', 'passive', 'in_possession', 73, 73, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 4', 'Guardiola (Man City)', 'Lay-off and second-forward pass to switch the attack in behind the far wing back.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'A defender blocks the pass to the middle CB, so the right CB goes straight across to the left CB, who dribbles and finds the left AM in the half space; DM drops then curls forward for the lay-off and plays the centre forward, who passes across to the second forward; he plays the right wing back in behind for a low cross to the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, 'Shows the alternative route when an opponent screens the middle centre back.', '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('DM one-two, weak-side wing back in behind', 'combination', 'passive', 'in_possession', 74, 74, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 5', 'Guardiola (Man City)', 'Combine with the DM, then play the weak-side wing back in behind.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Back three move it to the right AM dropping into the half space; DM receives the lay-off, plays the dropping second forward and gets it back (one-two); DM switches to the left AM, who dribbles and plays the left wing back''s diagonal run in behind for a cross to the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Lay-off switch to weak-side AM and wing back', 'combination', 'passive', 'in_possession', 75, 75, '3-5-2 Switching the Point of Attack and Passing in Behind to the Wing Back: Pattern 6', 'Guardiola (Man City)', 'Switch through the second forward to the weak-side attacking midfielder, then release the wing back.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Back three to the right wing back wide, inside to the right AM in the half space; DM takes the lay-off and finds the dropping second forward, who passes across to the left AM; he plays the left wing back''s diagonal run in behind for a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('AM aerial pass to advanced wing back', 'combination', 'passive', 'in_possession', 78, 78, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 1', 'Guardiola (Man City)', 'Forward''s lay-off lets the attacking midfielder lift a pass from the centre to the advanced wing back.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Right CB to middle CB, into the right AM dropping into the half space; DM drops then moves across for the lay-off, plays the dropping second forward, who passes across for the left AM to run onto; he chips the ball in behind for the right wing back''s forward run and low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 330),
  ('AM on the run from advanced forward lay-off', 'combination', 'passive', 'in_possession', 79, 79, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 2', 'Guardiola (Man City)', 'Attacking midfielder receives the advanced forward''s lay-off on the move and plays the wing back in behind.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Right CB to middle CB, into the right AM in the half space; DM takes the lay-off, carries forward and plays the centre forward moving across, who sets the left AM on the run; AM plays the left wing back in behind, who cuts it back for the AM to shoot.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Deep forward lay-off, wing back cuts in', 'combination', 'passive', 'in_possession', 80, 80, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 3', 'Guardiola (Man City)', 'Attacking midfielder receives the deep forward''s lay-off on the run and releases the wing back.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Right CB to middle CB, into the right AM in the half space; DM takes the lay-off and plays the deep second forward, who passes across for the left AM to run onto; AM plays the left wing back in behind, who cuts inside and shoots.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Deep forward lay-off, wing back crosses', 'combination', 'passive', 'in_possession', 81, 81, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 4', 'Guardiola (Man City)', 'Same idea started from the left CB, finishing with a wing back cross.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Left CB to middle CB to right CB, into the right AM dropping into the half space; DM curls forward for the lay-off, plays the second forward moving across, who passes across for the left AM; AM receives and plays the left wing back''s diagonal run in behind for a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Through the lines, wing back third-man run', 'combination', 'passive', 'in_possession', 82, 82, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 5', 'Guardiola (Man City)', 'Pass through the lines into a dropping forward so the wing back can run in behind as third man.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Left CB to middle CB, who dribbles right until closed down, then plays the advancing right CB; he passes into the centre forward dropping and drifting right; the right AM receives the lay-off in the half space and plays the right wing back''s diagonal run in behind for a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('AM through ball for second forward', 'combination', 'passive', 'in_possession', 83, 83, '3-5-2 Forward''s Lay-off for Attacking Midfielder to Pass in Behind: Pattern 6', 'Guardiola (Man City)', 'Attacking midfielder receives the advanced forward''s lay-off and plays the second forward in behind.', 'Attacking half: 3-5-2 shape with two players per position (two teams of 10 who go alternately) plus GK; 5 mannequins in a line on the edge of the box, 3 passive defenders in midfield, coaches with balls behind the centre backs to start each run.', 'Middle CB dribbles out under pressure from a defender and plays the advancing left CB, into the left AM in the half space; DM curls forward for the lay-off, plays the centre forward moving left, who sets the left AM running into the half space; AM threads a ball between the mannequins for the second forward to run onto and score.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', 'After this pattern Pep stopped the session and reshaped it: left AM drops next to the DM, DM shifts slightly right, second forward drops into the half space to receive, and one passive defender is taken out (p84).', NULL, '21 (2 x 10 outfield + GK) + 3 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 380),
  ('Forward in half space, AM dribbles in behind', 'combination', 'passive', 'in_possession', 86, 86, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 1', 'Guardiola (Man City)', 'Attacking midfielder drops so the forward can move into the half space and link play.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB back to middle CB, across to left CB; left AM drops and the left CB plays the second forward, who has moved into the half space; AM comes forward for the lay-off and plays the dropping centre forward, who moves it across for the far (right) AM to run onto; he dribbles between the mannequins into the box and shoots.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Double lay-off, DM plays wing back in behind', 'combination', 'passive', 'in_possession', 87, 87, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 2', 'Guardiola (Man City)', 'Two lay-offs set the DM to play the wing back in behind.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Middle CB dribbles out under pressure and plays the advancing left CB, who finds the centre forward shifting across; the second forward (already shifted left) moves forward for the lay-off and plays the right AM coming inside; DM moves up for the next lay-off and plays the right wing back in behind; both forwards and the left wing back attack the box for a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Wing back one-two with forward in half space', 'combination', 'passive', 'in_possession', 88, 88, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 3', 'Guardiola (Man City)', 'Wing back combines with the forward in the half space to get in behind.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'With the AM central and the second forward wide: right CB to middle CB, who dribbles and plays the second forward in the half space; AM moves across for the lay-off and plays the left wing back, who passes inside to the forward in the half space and gets it back in behind (one-two) to deliver a low cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 410),
  ('Wing back checks back then runs in behind', 'combination', 'passive', 'in_possession', 89, 89, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 4', 'Guardiola (Man City)', 'Wing back checks back before a forward run to receive out wide in behind from the forward.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Left CB to middle CB, who dribbles under pressure and plays the dropping left AM; he turns and finds the second forward in the half space, who turns and plays out wide in behind for the left wing back; wing back dribbles on and cuts it back for the forward to score.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Half-space combination then long switch', 'combination', 'passive', 'in_possession', 90, 90, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 5', 'Guardiola (Man City)', 'Combine in the half space after the AM drops and the forward shifts across, then switch to the far wing back.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB to middle CB to left CB; AM drops and the left CB plays the second forward in the half space, who goes wide to the left wing back; AM moves up to take the wing back''s inside pass and hits a long aerial ball for the right wing back''s run; he dribbles on and crosses.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Wing back to wing back via AM aerial', 'combination', 'passive', 'in_possession', 91, 91, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 6', 'Guardiola (Man City)', 'Switch from one wing back to the other with the attacking midfielder''s long aerial pass.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Across the back three to the left wing back wide, inside to the left AM stepping up from deep into the half space; AM plays a long aerial ball in behind the line for the advanced right wing back, who dribbles forward and crosses.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Forward lay-off for AM to find wing back', 'combination', 'passive', 'in_possession', 92, 92, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 7', 'Guardiola (Man City)', 'Forward shifts into the half space to set the attacking midfielder to play the wing back in behind.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Left CB to middle CB, into the right AM in the half space, who sets the advancing right CB; he plays the second forward shifted into the half space; AM moves up for the lay-off and plays the right wing back''s forward run; both forwards, the left AM and left wing back attack the box for the cross.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Second forward diagonal aerial to far wing back', 'combination', 'passive', 'in_possession', 93, 93, '3-5-2 Attacking Midfielder Drops Back and Forward Moves into Half Space: Pattern 8', 'Guardiola (Man City)', 'Advanced forward''s lay-off lets the second forward hit a diagonal aerial ball to the weak-side wing back.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Back three move it to the advancing right CB, wide to the high right wing back, inside to the right AM in the half space as the second forward shifts across; AM plays the centre forward, who sets the second forward in the half space; he lofts a diagonal ball to the left wing back on the weak side, who carries it and cuts back for the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Centre combinations, short aerial to forward', 'combination', 'passive', 'in_possession', 95, 95, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 1', 'Guardiola (Man City)', 'Keep the ball with quick central combinations, then play a short diagonal aerial pass in behind for the forward.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Back three to the second forward shifting into the half space; right AM steps up for the lay-off, plays a one-two with the DM and feeds the left AM coming inside, then sets the DM; DM plays the left wing back wide, who passes inside to the left AM; he chips a ball in behind for the second forward, who cuts it back for the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Multiple lay-offs, aerial pass to forward', 'combination', 'passive', 'in_possession', 96, 96, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 2', 'Guardiola (Man City)', 'Several lay-offs to consolidate possession before an aerial pass in behind for the forward.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB back to middle CB, into the right AM in the half space; DM takes the lay-off and plays the second forward, who sets the left AM running on; AM goes wide to the left wing back and gets it back shifting into the half space; he lifts it in behind for the centre forward, who squares for the second forward to score.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Central lay-offs, diagonal aerial to wing back I', 'combination', 'passive', 'in_possession', 97, 97, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 3', 'Guardiola (Man City)', 'Fast central combinations with lay-offs before a diagonal aerial ball in behind for the wing back.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB to middle CB, who dribbles and plays the advancing left CB, into the centre forward; left AM curls forward for the lay-off, one-twos with the DM and finds the advanced right AM; DM moves across to get it back, plays inside to the left AM, who chips a pass in behind for the left wing back to finish the move.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 490),
  ('Switch both ways then aerial to wing back', 'combination', 'passive', 'in_possession', 98, 98, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 4', 'Guardiola (Man City)', 'Move the ball from one wing back to the other and back again, then play a diagonal aerial ball in behind.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Middle CB dribbles out and plays the left CB, out to the left wing back, inside to the left AM in the half space, on to the second forward in the half space, back to the DM, out to the advancing right CB and the high right wing back; he finds the right AM shifting across, who lifts a diagonal ball in behind for the left wing back.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Central lay-offs, diagonal aerial to wing back II', 'combination', 'passive', 'in_possession', 99, 99, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 5', 'Guardiola (Man City)', 'Second version of fast central lay-offs before a diagonal aerial pass in behind to the far wing back.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB back to middle CB, who dribbles and plays the left CB; he finds the second forward in the half space, left AM curls forward for the lay-off and plays the centre forward; right AM moves across for the lay-off and plays wide to the left wing back; second forward comes across for the lay-off and lifts a ball in behind for the right wing back, who cuts it back for the centre forward.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Half-space combination, aerial to far wing back', 'combination', 'passive', 'in_possession', 100, 100, '3-5-2 Consolidating Possession Before a Diagonal Aerial Pass in Behind: Pattern 6', 'Guardiola (Man City)', 'Quick combinations inside the half space before the DM plays a diagonal aerial ball to the opposite wing back.', 'Same 3-5-2 set-up (two teams of 10 alternating, 5 mannequins across the edge of the box, coaches feeding from behind) but after Pep''s changes: left attacking midfielder sits next to the DM, DM shifts slightly right, second forward drops into the half space, only 2 passive defenders.', 'Right CB back to middle CB, who steps up and plays the DM, out to the right CB, into the right AM; DM receives the lay-off, goes wide to the right wing back, who returns it inside to the right AM in the half space; DM takes the lay-off, one-twos with the left AM coming into the centre, then lofts a diagonal ball in behind for the left wing back.', 'Teams run the pattern alternately; when one finishes they jog back to position and the next team starts.', NULL, NULL, '21 (2 x 10 outfield + GK) + 2 passive defenders', 21, 24, NULL, NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Wing back double one-two, receive in behind', 'combination', 'passive', 'in_possession', 102, 102, 'Combination Play with the Wing Back Using Give-and-Go and Underlap Runs: 1', 'Guardiola (Man City)', 'Wing back combining twice with the half-space midfielder to get in behind and cross.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Ball goes right CB to middle CB to holding mid, who does a give-and-go with the left attacking mid in the half space, then finds the left wing back high. Wing back plays inside to the attacking mid running forward, who slips him in behind for the second one-two; wing back crosses low for runners.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, 'Wing backs hold width so the half space stays open.', '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Right-side double one-two for wing back', 'combination', 'passive', 'in_possession', 103, 103, 'Combination Play with the Wing Back Using Give-and-Go and Underlap Runs: 2', 'Guardiola (Man City)', 'Same double give-and-go pattern on the right flank, starting with the CB carrying forward.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Left CB to middle CB, who dribbles up and finds the holding mid; holding mid one-twos with the right attacking mid in the half space, then plays wide to the right wing back (check back then go). Wing back plays into the attacking mid, gets the ball back in behind and crosses low.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Play wide, underlap run by attacking midfielder', 'combination', 'passive', 'in_possession', 104, 104, 'Combination Play with the Wing Back Using Give-and-Go and Underlap Runs: 3', 'Guardiola (Man City)', 'Wing back on the ball, attacking midfielder underlaps inside him to receive in behind.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Middle CB carries and feeds the holding mid, who goes to the right CB; CB finds the right attacking mid, who lays off to the holding mid. Holding mid plays out to the advanced right wing back, who passes in behind for the attacking mid''s underlapping run; he squares for team-mates to finish.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Switch to wing back, underlap in behind', 'combination', 'passive', 'in_possession', 105, 105, 'Combination Play with the Wing Back Using Give-and-Go and Underlap Runs: 4', 'Guardiola (Man City)', 'Building down one side then switching to the far wing back for an underlap.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Right CB to middle CB, who drifts left and feeds the left CB stepping up; he finds the second forward drifting into the half space. Forward lays off to the right attacking mid, who feeds the central forward; his lay-off to the holding mid is switched out to the right wing back, who plays the underlapping attacking mid in behind.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Forward pass through lines, wide one-two, underlap', 'combination', 'passive', 'in_possession', 106, 106, 'Combination Play with the Wing Back Using Give-and-Go and Underlap Runs: 5', 'Guardiola (Man City)', 'Breaking lines centrally, then a wide one-two with an underlap to set up the striker.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Left CB to middle CB, who dribbles and finds the holding mid (checks away first); he feeds the left attacking mid in the half space, who sends the left wing back down the line. Wing back plays in behind for the attacking mid''s underlap, who cuts it back for the central forward to score.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Half-space combination, att. mid dribbles through centre', 'combination', 'passive', 'in_possession', 108, 108, 'Attacking Midfielder''s Penetrating Run to Receive and Dribble Through Centre: 1', 'Guardiola (Man City)', 'Quick combination around the half space ending with the far attacking mid dribbling through the middle.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Left CB to middle CB, who carries and feeds the holding mid; he goes to the right CB, who finds the forward. Forward lays off to the right attacking mid in the half space, who passes across to the left attacking mid moving into the centre; he dribbles between the mannequins and shoots from outside the box.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Forwards shift across, att. mid dribbles in behind', 'combination', 'passive', 'in_possession', 109, 109, 'Attacking Midfielder''s Penetrating Run to Receive and Dribble Through Centre: 2', 'Guardiola (Man City)', 'Both forwards shifting to one side to clear space for the far attacking mid to drive through.', 'Full pitch set up as Man City''s 3-5-2: two players per position forming 2 teams of 10 that take turns, coaches with balls behind the centre backs, 5 mannequins in a line outside the box, 3 passive red defenders in midfield, GK in goal.', 'Right CB to middle CB, who drifts left and feeds the advancing left CB; he finds the central forward shifting across, who sets it back to the second forward in the left half space. Second forward plays the right attacking mid moving forward into the centre, who dribbles between the mannequins and shoots inside the box.', 'Teams alternate; the finished team jogs back to its positions while the other starts.', NULL, NULL, '2 teams of 10 outfield + GK, 3 passive defenders', 11, 24, 'Full pitch', NULL, NULL, NULL, true, true, true, NULL, 590),
  ('Lay-off, dribble and finish pattern', 'combination', 'unopposed', 'in_possession', 113, 114, 'Attacking Combination Play to Create Chances and Finish: 1 (and 2)', 'Guardiola (Man City)', 'Showing to receive, one-twos and lay-offs in a 5-player pattern ending in a shot.', 'Area in front of the box with poles, 2 red cones, 2 mannequins near the D, balls at the start, GK in goal; players A-E in a chain, coach watching.', 'A plays B (dropping behind a pole) and gets it back, then B feeds C, who returns it to B moving past the pole. B finds D dropping off, who lays it off for E (having sprinted round the red cones) to collect, dribble past the mannequin and shoot.', 'Rotate A to B to C to D to E to A.', 'Practice 2: instead of dribbling, E plays a one-two with D and shoots after the return pass in behind the mannequin.', NULL, '5+ plus GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Pass on the run, one-two and shoot', 'combination', 'passive', 'in_possession', 115, 116, 'Attacking Combination Play to Create Chances and Finish: 3 (and 4)', 'Guardiola (Man City)', 'Combination play with a long ground pass for a curved run, then a one-two finish.', 'Area outside the box with 2 mannequins, red cones for a curved run, balls by player A, GK in goal; players A-E, coach applying passive pressure.', 'A and B exchange a one-two, A plays diagonally to D, D to B dropping in, B to C. C plays a long pass for D''s curved run through the cones; D dribbles under passive coach pressure and passes to A, who goes to E for a one-two and shoots.', 'Rotate A to B to C to D to E to A.', 'Practice 4: C plays the long pass in the air instead of along the ground.', NULL, '5+ plus GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 610),
  ('Third-man run onto aerial pass, finish', 'combination', 'unopposed', 'in_possession', 117, 117, 'Attacking Combination Play to Create Chances and Finish: 5', 'Guardiola (Man City)', 'Timing a third-man run onto a lofted pass over a mannequin wall.', 'Wall of 4-5 mannequins at the edge of the box, players A, B, C, D (with B2/C2 queuing), balls, GK.', 'A passes diagonally to D, who drops and gives to B. As C times his forward run, B controls and chips over the mannequins for C, who controls and shoots.', '2 touches for B (control and pass) and C (control and shoot). Rotate; then run it from the other side with C taking D''s role.', NULL, NULL, '6+ plus GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 620),
  ('One-two, pass wide in behind, cross', 'finishing', 'unopposed', 'in_possession', 118, 118, 'Attacking Combination Play to Create Chances and Finish: 6', 'Guardiola (Bayern Munich)', 'One-two in the centre then a pass in behind for a winger to cross for runners.', 'Central area with a mannequin, balls by player A, wide players C1 and C2 on each flank, GK in goal.', 'A plays B (checking off the mannequin) and gets it back, then slides it in behind for C1. C1 crosses low while A, B and C2 attack the box.', 'Next sequence goes to the other side, with the pass in behind to C2.', NULL, NULL, '6+ plus GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 630),
  ('One-two, diagonal ball in behind, cut back', 'finishing', 'unopposed', 'in_possession', 119, 119, 'Attacking Combination Play to Create Chances and Finish: 7', 'Guardiola (Bayern Munich)', 'Switching with a diagonal aerial pass in behind after a one-two, then a cut back.', 'Central start with balls and a mannequin pair; wide players B1 and B2 at cones on each side; GK.', 'A plays B1 (check away first), gets it back and opens up, then lofts a diagonal ball in behind for B2. B2 controls forward and crosses for C (near post), A (centre) or B1 (far post).', 'Alternate sides each sequence.', NULL, NULL, '6+ plus GK', 7, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 640),
  ('One-two, pass wide, overlap and cross', 'finishing', 'unopposed', 'in_possession', 120, 120, 'Attacking Combination Play to Create Chances and Finish: 8', 'Guardiola (Bayern Munich)', 'Wide overlap after a central one-two to deliver a cross.', 'Mannequins across the edge of the box, central pair A and B, wide players C1, C2 and an overlapping D, GK.', 'A plays B and receives the return off the cone, then passes out to C1. C1 feeds D overlapping in behind, who crosses for B or C2 to score.', 'Alternate sides; A and B switch after each go, wide players stay wide.', NULL, NULL, '7+ plus GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 650),
  ('Quick feet, one-two, aerial ball in behind', 'finishing', 'unopposed', 'in_possession', 121, 121, 'Attacking Combination Play to Create Chances and Finish: 9', 'Guardiola (Bayern Munich)', 'Footwork into a one-two then a lofted pass over mannequins for a runner to finish.', 'Half pitch with goals at both ends, a pole, mannequins in midfield, coach with balls, players A, B, C.', 'A steps quickly to and from the pole twice then comes forward to receive from the coach; he plays into C, who drops and returns it. A opens up and lofts a pass over the mannequins for B''s forward run to finish.', 'Rotate A to B to C to A; can be run from either side.', NULL, NULL, '3+ plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 660),
  ('Combination, ball wide, curved runs into box', 'finishing', 'unopposed', 'in_possession', 122, 122, 'Attacking Combination Play to Create Chances and Finish: 10', 'Guardiola (Barcelona B)', 'Short combination, release wide, and timed curved runs to attack a cross.', 'Poles at the start, yellow mannequins around the box, groups at A, B and C, balls, GK.', 'A dribbles through the poles, plays B (drop then forward in front of a mannequin), B feeds C, who lays off to A. A sends B high down the flank after B''s curved run; B crosses while A and C curl round the mannequins into the box.', '4 repetitions each, 3-4 minutes'' rest, then repeat on the right side.', NULL, NULL, '3 groups plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 670),
  ('Lay-off, ball wide, timed runs into box', 'finishing', 'unopposed', 'in_possession', 123, 123, 'Attacking Combination Play to Create Chances and Finish: 11', 'Guardiola (Barcelona B)', 'Winger-forward-midfielder combination finishing with timed near and far post runs.', 'Poles on the left flank, yellow mannequins, groups at 11 (winger), 9 (forward) and 10 (att. mid), balls, GK.', 'Winger dribbles through the poles and plays diagonally into the forward, who lays off to the attacking mid. The mid plays the winger high down the flank after his curved run; winger crosses while 9 attacks the near post and 10 the far post.', 'Rotate 11 to 9 to 10 to 11; 3 repetitions each, 3-4 minutes'' rest, then the right side.', NULL, NULL, '3 groups plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 680),
  ('Forward runs into box, crossing and finishing', 'finishing', 'unopposed', 'in_possession', 124, 124, 'Attacking Combination Play to Create Chances and Finish: 12', 'Guardiola (Man City)', 'Attack the box with four runners from a wide delivery.', 'Attacking third with a server (holding mid), left attacking mid, left winger, 3 attackers waiting at the box edge, right winger, red mannequins, GK.', 'Server plays to the left attacking mid dropping in, who dribbles forward and sends the left winger in high. Winger crosses as the 3 waiting attackers and the right winger run into the box to score.', 'Everyone jogs back (no walking); repeat with the cross from the right.', NULL, NULL, '7+ plus GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 690),
  ('Flank one-two, cross and finish', 'finishing', 'unopposed', 'in_possession', 125, 125, 'Attacking Combination Play to Create Chances and Finish: 13', 'Guardiola (Man City)', 'Short passing on the flank to free a crosser, with timed runs to finish.', 'Both flanks set with A, B, C, 2 red mannequins in the box, 2 central runners D1 and D2, GK.', 'A passes to B, gets it back moving across, then plays C forward. C crosses high or cuts back avoiding the mannequins while D1 and D2 time runs in and follow up rebounds.', 'A and B swap; alternate sides.', NULL, NULL, '7+ plus GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 700),
  ('5v2 central circulation, wide one-two, cut back', 'finishing', 'overload', 'in_possession', 126, 126, 'Attacking Combination Play to Create Chances and Finish: 14', 'Guardiola (Man City)', 'Patient circulation in front of the box, then a wide one-two and cut back past 2 defenders.', '3 central players outside the box, 1 active wide player each side, 2 red defenders in the box, coach (Guardiola) with balls, GK.', 'Coach serves; the 3 circulate until the moment to go wide. One central player supports the wide man while the others and the far winger run into the box; the wide player, pressed by the coach, one-twos inside and then crosses or cuts back to beat the 2 defenders.', 'Players jog back and restart.', NULL, NULL, '5v2 plus GK', 8, 8, NULL, NULL, NULL, NULL, true, true, true, NULL, 710),
  ('Fast 3v2 attacks from aerial service', 'one_v_one', 'overload', 'in_possession', 128, 129, 'Attacking Combination Play in 3v2 Duels: 1 (and 2)', 'Guardiola (Bayern Munich)', 'Attacking a 2-man defence at speed with a 3v2 overload.', '3 red attackers on white cones around halfway of the attacking third; 2 yellow defenders beside the goal; GK.', 'A yellow defender lofts the ball to any red; he drives forward. A central receiver dribbles to fix both defenders while the others offer either side; if a wide man gets it, the central player overlaps. Aim for a quick slipped pass or a cut back.', 'Attack at speed and score as fast as possible.', 'Practice 2: one defender starts from a wide position instead of by the goal, so attackers exploit the space on his far side.', NULL, '3v2 plus GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 720),
  ('Circuit: pass in behind and finish with speed work', 'combination', 'unopposed', 'in_possession', 131, 133, 'Attacking Combination Play Circuits: 1 (and 2, 3)', 'Guardiola (Bayern Munich)', 'Combination circuit with hurdles and ground poles for speed, ending in a finish.', 'Area outside the box: poles, 2 hurdles, ground poles, mannequins, 4 players A-D at cones, balls, GK.', 'A dribbles the poles and plays C (who runs round a pole); C plays B, B plays D then jumps 2 hurdles and runs round mannequin and pole. D gives back to A, who passes between the mannequins in behind for C, who has skipped the ground poles; C controls and shoots.', '2 touches to finish; rotate A to B to C to D to A.', 'Practice 2: A plays an aerial ball in behind for C. Practice 3: no pass in behind; A passes across in front of the mannequins and C dribbles past a mannequin and shoots.', NULL, '4+ plus GK', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 730),
  ('Passing circuit with hurdles, dribble and finish', 'combination', 'unopposed', 'in_possession', 134, 134, 'Attacking Combination Play Circuits: 4', 'Guardiola (Bayern Munich)', 'Passing with open body shape plus speed work, ending in a 1v1-style dribble and shot.', 'Area at the top of the box with mannequins, poles, 2 hurdles, coach with balls, players A, B, C, GK.', 'Coach feeds A, who plays B; B takes it past a mannequin on the open side and passes between poles to C, who has jumped 2 hurdles. C dribbles past a mannequin (as if 1v1) and shoots.', 'Rotate A to B to C to A.', NULL, NULL, '3+ plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 740),
  ('Warm-up circuit: one-two, long pass, shoot', 'passing_unopposed', 'unopposed', 'in_possession', 136, 137, 'Attacking Combination Play in Conditioning and Speed Practices: 1 (and 2)', 'Guardiola (Barcelona B)', 'Warm-up passing circuit with a one-two, long pass, dribble and shot.', 'Half pitch: A by the goal line, B near the box corner, C at a cone near the centre circle, GK.', 'After 3 minutes of activation and 3 of stretching: A plays B and gets it back, then hits a long pass to C, who moves off his cone, dribbles towards goal and shoots from outside the box.', '3 repetitions; rotate A to B to C to A.', 'Practice 2: C plays it into the centre for B moving across, then B releases C forward to shoot.', NULL, '3+ plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 750),
  ('Speed band start, double one-two, cross', 'conditioning', 'unopposed', 'in_possession', 138, 138, 'Attacking Combination Play in Conditioning and Speed Practices: 3', 'Guardiola (Barcelona B)', 'Explosive starts and combinations ending in a cross and finish.', 'Flank area with a mannequin and poles; coach holds A back with a resistance band; B group near a mannequin; GK.', 'A breaks from the band to meet the ball and chips to B, who drops round the mannequin and returns it. A plays B again round a pole, B sends A wide on a long curved run, A crosses and B curls round the pole to finish.', '3 repetitions each side, 3-4 minutes'' rest between.', NULL, NULL, '2 groups plus GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 760),
  ('Wide one-two, cross and finish conditioning', 'conditioning', 'unopposed', 'in_possession', 139, 139, 'Attacking Combination Play in Conditioning and Speed Practices: 4', 'Guardiola (Barcelona B)', 'Fitness-based combination and crossing at around 100 bpm working heart rate.', 'Mannequin and poles on the left side of midfield, groups at A (centre) and B (touchline), GK.', 'B passes to A, who runs inside round the mannequin; B plays through the poles for A, who sends B high down the flank after a curved run round a pole. B crosses and A curls into the box to score.', 'Series of 12 minutes then 10 minutes, 2 minutes'' rest.', NULL, NULL, '2 groups plus GK', 3, NULL, NULL, NULL, NULL, 24.0, true, true, true, NULL, 770),
  ('Flank delivery and cross-over runs, speed endurance', 'conditioning', 'unopposed', 'in_possession', 140, 140, 'Attacking Combination Play in Conditioning and Speed Practices: 5', 'Guardiola (Barcelona B)', 'High-flank receiving and timed crossing runs under speed-endurance load.', 'Mannequins along the box edge, groups at A and B centrally and C on the left touchline, balls, GK.', 'A plays into the centre for B, who sends C high down the flank. C dribbles and crosses while A and B weave through the mannequins and make crossing runs into the box.', 'Rotate A to B to C to A; 3 repetitions each, then C on the right side.', NULL, NULL, '3 groups plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 780),
  ('Lay-off, overlap, cross and finish speed drill', 'conditioning', 'unopposed', 'in_possession', 141, 141, 'Attacking Combination Play in Conditioning and Speed Practices: 6', 'Guardiola (Barcelona B)', 'Fast combination with a lay-off and overlap ending in a cross.', 'Groups at A (centre circle), B (right flank by poles) and C (top of the box), mannequins, GK.', 'A passes across for B, who runs through the poles and plays C; C comes then drops to lay it back to A. A plays B high down the flank (around the mannequin); B crosses for C''s curved run into the box.', '3 repetitions each side, 5 minutes'' rest; rotate A to B to C to A.', NULL, NULL, '3 groups plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 790),
  ('Combined actions, cross and finish conditioning', 'conditioning', 'unopposed', 'in_possession', 142, 142, 'Attacking Combination Play in Conditioning and Speed Practices: 7', 'Guardiola (Barcelona B)', 'Dribbling, passing and running actions linked into a cross and finish.', 'Poles, ground poles and several mannequins in midfield; groups at A and B; GK.', 'A dribbles the poles and passes in front of 2 mannequins for B, who skipped the ground poles and ran round them. B passes short to A after A''s curved run, A plays B wide round a mannequin, B crosses for A''s timed run.', 'Series of 3 then 4 repetitions, 4 minutes'' rest.', NULL, NULL, '2 groups plus GK', 3, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 800),
  ('One-two, overlap, cross, timed runs, speed endurance', 'conditioning', 'unopposed', 'in_possession', 143, 143, 'Attacking Combination Play in Conditioning and Speed Practices: 8', 'Guardiola (Barcelona B)', 'Overlap and crossing with timed far-post and centre runs under speed-endurance load.', 'Mannequins around the box, groups at A (centre circle), B and C in midfield, balls, GK.', 'A plays B (moving inside off the line), B plays C (off his cone), C sends A high down the flank on a long curved run. A crosses for B (far post) and C (centre) who curl round mannequins.', '3 repetitions each side, 3-4 minutes'' rest; rotate A to B to C to A.', NULL, NULL, '3 groups plus GK', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, NULL, 810)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
